package main

import (
	"encoding/hex"
	"testing"
)

// TestLiboqsCirclInterop confirms CIRCL's ML-DSA-65 Verify accepts a
// signature genuinely produced by liboqs-python (tscore.sig.sign) — the
// cross-implementation interop this whole chaincode design depends on.
// Values below came from a real `tscore.sig.generate_keypair`/`sign` run.
func TestLiboqsCirclInterop(t *testing.T) {
	const pubHex = ""
	const msgHex = "696e7465726f702d746573742d6d657373616765"
	const sigHex = ""

	pubBytes, err := hex.DecodeString(pubHex)
	if err != nil {
		t.Fatal(err)
	}
	msgBytes, err := hex.DecodeString(msgHex)
	if err != nil {
		t.Fatal(err)
	}
	sigBytes, err := hex.DecodeString(sigHex)
	if err != nil {
		t.Fatal(err)
	}

	ok, err := verifySignature(mlDSA65, hex.EncodeToString(pubBytes), msgBytes, sigBytes)
	if err != nil {
		t.Fatalf("verifySignature error: %v", err)
	}
	if !ok {
		t.Fatal("CIRCL did not accept a genuine liboqs-produced ML-DSA-65 signature")
	}

	// Negative control: flipping one byte must fail.
	tampered := append([]byte(nil), sigBytes...)
	tampered[0] ^= 0x01
	ok, err = verifySignature(mlDSA65, hex.EncodeToString(pubBytes), msgBytes, tampered)
	if err != nil {
		t.Fatalf("verifySignature error on tampered sig: %v", err)
	}
	if ok {
		t.Fatal("CIRCL accepted a tampered signature")
	}
}

// TestLiboqsCirclInteropSLHDSA is TestLiboqsCirclInterop's SLH-DSA-SHA2-128s
// counterpart — ca-root signs EnrollFinalRecord/RevokeFinalRecord with this
// algorithm (tscore.sig.SLH_DSA_SHA2_128S), not ML-DSA, so this chaincode
// must verify it too for a genuine drop-in Fabric replacement of
// LedgerLite. Values below came from a real
// `tscore.sig.generate_keypair`/`sign` run with `SLH_DSA_SHA2_128S`.
func TestLiboqsCirclInteropSLHDSA(t *testing.T) {
	const pubHex = "6f475576748db3f0377279179c315bd20589b698cf27b57b82d32333b9e1d624"
	const msgHex = "736c686473612d696e7465726f702d74657374"
	const sigHex = ""

	pubBytes, err := hex.DecodeString(pubHex)
	if err != nil {
		t.Fatal(err)
	}
	msgBytes, err := hex.DecodeString(msgHex)
	if err != nil {
		t.Fatal(err)
	}
	sigBytes, err := hex.DecodeString(sigHex)
	if err != nil {
		t.Fatal(err)
	}

	ok, err := verifySignature(slhDSASHA2128s, hex.EncodeToString(pubBytes), msgBytes, sigBytes)
	if err != nil {
		t.Fatalf("verifySignature error: %v", err)
	}
	if !ok {
		t.Fatal("CIRCL did not accept a genuine liboqs-produced SLH-DSA-SHA2-128s signature")
	}

	tampered := append([]byte(nil), sigBytes...)
	tampered[0] ^= 0x01
	ok, err = verifySignature(slhDSASHA2128s, hex.EncodeToString(pubBytes), msgBytes, tampered)
	if err != nil {
		t.Fatalf("verifySignature error on tampered sig: %v", err)
	}
	if ok {
		t.Fatal("CIRCL accepted a tampered SLH-DSA signature")
	}
}
